import React from 'react';
import { Workflow } from '../types';

type CanvasProps = {
    workflow?: Workflow | null;
};

const Canvas: React.FC<CanvasProps> = ({ workflow }) => {
    return (
        <div className="canvas">
            {/* This is where the workflow design interface will be implemented */}
            {workflow ? <pre style={{fontSize:12, color:'#374151'}}>{JSON.stringify(workflow, null, 2)}</pre> : null}
        </div>
    );
};

export default Canvas;
